# owner: platform
import unittest

from rosterkit.contacts import ContactError, contact_rows
from rosterkit.models import Student


def make_student(last, first, section, email="x@y.org"):
    return Student("id", last, first, section, email)


class ContactRowsTests(unittest.TestCase):
    def test_rows_are_sorted_by_name(self):
        rows = contact_rows([
            make_student("Young", "Zed", "B"),
            make_student("Adams", "Amy", "A")
        ])
        self.assertTrue(rows[0].startswith("Adams, Amy"))
        self.assertTrue(rows[1].startswith("Young, Zed"))

    def test_columns_are_lined_up(self):
        rows = contact_rows([
            make_student("Li", "Al", "A", "al@y.org"),
            make_student("Longname", "Bo", "B", "bo@y.org")
        ])
        self.assertEqual(rows[0].index("A "), 14)
        self.assertEqual(rows[1].index("B "), 14)
        self.assertEqual(rows[0].index("al@"), 17)
        self.assertEqual(rows[1].index("bo@"), 17)

    def test_row_has_name_section_and_email(self):
        rows = contact_rows([make_student("Li", "Al", "A")])
        self.assertEqual(rows, ["Li, Al  A  x@y.org"])

    def test_missing_email_names_the_student(self):
        students = [make_student("Li", "Al", "A", None)]
        with self.assertRaises(ContactError) as caught:
            contact_rows(students)
        self.assertIn("Li, Al", str(caught.exception))

    def test_blank_email_is_missing(self):
        students = [make_student("Li", "Al", "A", "  ")]
        with self.assertRaises(ContactError):
            contact_rows(students)

    def test_empty_list_raises(self):
        with self.assertRaises(ContactError):
            contact_rows([])


if __name__ == "__main__":
    unittest.main()
